// Home photos embedded (1200px JPEG) so single-file bundles keep them. Remaps 'photos/home-N.png' to inline data.
window.KLYR_PHOTOS = {'photos/klyr-mark.png': 'data:image/png;base64,',
'photos/home-1.png': 'data:image/jpeg;base64,',
'photos/home-2.png': 'data:image/jpeg;base64,',
'photos/home-3.png': 'data:image/jpeg;base64,',
'photos/home-4.png': 'data:image/jpeg;base64,'};

(function(){ try { const M = window.KLYR_PHOTOS; for (const k in M) { const s = M[k], i = s.indexOf(','), bin = atob(s.slice(i + 1)), u8 = new Uint8Array(bin.length); for (let j = 0; j < bin.length; j++) u8[j] = bin.charCodeAt(j); M[k] = URL.createObjectURL(new Blob([u8], { type: s.slice(5, i).split(';')[0] })); } } catch (e) {} })();

// Swap any <img src="photos/..."> in the page for the embedded copy (works inside single-file bundles).
(function(){ const M = window.KLYR_PHOTOS; const fix = root => root.querySelectorAll('img[src^="photos/"]').forEach(im => { const k = im.getAttribute('src'); if (M[k]) im.src = M[k]; }); const go = () => { fix(document); new MutationObserver(ms => ms.forEach(m => m.addedNodes.forEach(n => { if (n.nodeType === 1) { if (n.matches && n.matches('img[src^="photos/"]')) fix(n.parentNode || document); else fix(n); } }))).observe(document.documentElement, { childList: true, subtree: true }); }; if (document.body) go(); else document.addEventListener('DOMContentLoaded', go); })();
